MATLAB 程序: exe606.m

\%滞后校正

w = 0.001:1:100;

G = tf([5],[conv([1,0],conv([1,1],[0.25,1]))]);

Gc = tf([16.95,1],[143.64,1]);

G1 = series(G,Gc);

[x,y] = bd_asymp(G,w);

[xc,yc] = bd_asym(Gc,w);

[x11,y11] = bd_asym(G1,w);

\%绘制系统校正前、滞后校正网络和校正后的对数幅频渐近线

figure(1);

semilogx(x,y,'r'); hold on;

semilogx(xc,yc,'b');

semilogx(x11,y11,'k');

grid; hold off

G11 = feedback(G1,1);

figure(2);step(G11);grid

